// Item 4 — RE-MEASURE the SVG size distribution on the OpenAI path.
//
// This is a NEW BASELINE, not a confirmation run. The existing CACHED_SVG_MAX_BYTES
// (8KB) was chosen against a max of 1318 B measured across 8 figures, ALL generated by
// Groq's 8b fallback under 429s — figures that turned out to be label-only, which is
// exactly why they were small. A model that actually draws each part, adds leader
// lines and positions labels outside the figure produces materially larger SVG.
//
// The failure mode this guards against is a good figure being rejected for being
// detailed. That would look identical to a generation failure in the logs.
import dotenv from 'dotenv';
import { generateDiagramFor, DIAGRAM_MODEL, CACHED_SVG_MAX_BYTES, MAX_SVG_BYTES_EXPORT, validateDepiction } from './src/utils/generateDiagram.js';
dotenv.config();

// A deliberate spread across the four figure families the app actually generates.
// Biology cross-sections are expected to be the largest — most parts, most labels.
const CASES = [
  { family: 'geometry', chapter: 'Circles', grade: 'Class 10', subject: 'Maths',
    q: 'In a circle with centre O, a chord AB subtends an angle at the centre. Which statement about the perpendicular from O to AB is correct?' },
  { family: 'geometry', chapter: 'Triangles', grade: 'Class 10', subject: 'Maths',
    q: 'Two triangles ABC and PQR have their corresponding angles equal. Which criterion establishes their similarity?' },
  { family: 'optics', chapter: 'Light — Reflection and Refraction', grade: 'Class 10', subject: 'Science',
    q: 'A ray of light strikes a concave mirror parallel to its principal axis. Where does the reflected ray pass?' },
  { family: 'optics', chapter: 'Light — Reflection and Refraction', grade: 'Class 10', subject: 'Science',
    q: 'A ray of light passes from air into a glass slab. How does the emergent ray relate to the incident ray?' },
  { family: 'circuits', chapter: 'Electricity', grade: 'Class 10', subject: 'Science',
    q: 'Three resistors are connected in series across a cell. Which quantity is the same through each resistor?' },
  { family: 'circuits', chapter: 'Electricity', grade: 'Class 10', subject: 'Science',
    q: 'Two resistors are connected in parallel across a battery with an ammeter in the main circuit. What does the ammeter read?' },
  { family: 'biology', chapter: 'Life Processes', grade: 'Class 10', subject: 'Science',
    q: 'Which structure in a plant cell carries out photosynthesis, and where is it located relative to the cell wall and vacuole?' },
  { family: 'biology', chapter: 'Life Processes', grade: 'Class 10', subject: 'Science',
    q: 'In the human excretory system, which part of the nephron is responsible for filtration of blood?' },
  { family: 'biology', chapter: 'Life Processes', grade: 'Class 10', subject: 'Science',
    q: 'Identify the parts of the human heart through which deoxygenated blood enters and leaves.' },
  { family: 'biology', chapter: 'Control and Coordination', grade: 'Class 10', subject: 'Science',
    q: 'Which parts of a neuron receive and transmit the nerve impulse?' }
];

console.log(`SVG size baseline — model: ${DIAGRAM_MODEL}`);
console.log(`current CACHED_SVG_MAX_BYTES = ${CACHED_SVG_MAX_BYTES}\n`);

const rows = [];
for (const c of CASES) {
  // Measured against the GENERAL cap, not the cached one — the point is to find out
  // how big real figures are, not to observe them being clipped by the cap under test.
  const res = await generateDiagramFor(
    { questionText: c.q, options: ['A', 'B', 'C', 'D'] },
    { grade: c.grade, subject: c.subject, subSubject: '', chapterName: c.chapter, maxBytes: 50 * 1024 }
  );
  const svg = res?.diagram?.svg || '';
  const bytes = svg ? Buffer.byteLength(svg, 'utf8') : 0;
  const dep = svg ? validateDepiction(svg) : { stats: {} };
  rows.push({ ...c, status: res?.status, bytes, stats: dep.stats });
  console.log(`${String(bytes).padStart(6)} B  ${c.family.padEnd(9)} ${res?.status.padEnd(9)} ` +
    `shapes=${dep.stats?.drawings ?? '-'} labels=${dep.stats?.texts ?? '-'} leaders=${dep.stats?.leaders ?? '-'}  ${c.chapter}`);
}

const sized = rows.filter((r) => r.bytes > 0).map((r) => r.bytes);
console.log('\n── baseline ──────────────────────────────');
if (!sized.length) {
  console.log('NO FIGURES GENERATED — the measurement is INCONCLUSIVE, not a result of "small figures".');
  process.exit(1);
}
const min = Math.min(...sized), max = Math.max(...sized);
const avg = Math.round(sized.reduce((a, b) => a + b, 0) / sized.length);
console.log(`figures generated : ${sized.length}/${CASES.length}`);
console.log(`min / avg / max   : ${min} B / ${avg} B / ${max} B`);
console.log(`previous baseline : 402 B / 547 B / 1318 B   (Groq 8b under 429s, label-only)`);
console.log(`growth at the max : ${(max / 1318).toFixed(1)}x`);
console.log(`headroom at 8KB   : ${(CACHED_SVG_MAX_BYTES / max).toFixed(1)}x the largest measured`);

// Per-family, because biology is expected to dominate and a single max hides that.
const byFamily = {};
for (const r of rows) {
  if (!r.bytes) continue;
  (byFamily[r.family] ||= []).push(r.bytes);
}
console.log('\nper family (max):');
for (const [fam, list] of Object.entries(byFamily)) {
  console.log(`  ${fam.padEnd(9)} n=${list.length}  max=${Math.max(...list)} B`);
}

const RECOMMEND_RAISE = max > CACHED_SVG_MAX_BYTES * 0.5;
console.log(`\nverdict: ${RECOMMEND_RAISE
  ? `RAISE THE CAP — the largest figure is within 2x of it, so a more detailed one will be silently rejected.`
  : `cap is adequate — largest figure is under half of it.`}`);
